detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — for example, maximize the number of complete products (each requiring one unit of each of the three components), maximize total component output, or minimize cost?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a demand or sales limit on the number of complete products that can be sold, or is the only limit the workshops' production capacity?"
  ],
  "rationale": "The response asks a single clarification question regarding the source of the limit on product sales."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a workshop split its hours across all three components (i.e., produce any mix of components 1, 2, and 3), or is each workshop restricted to producing only one specific component?"
  ],
  "rationale": "The response asks a single clarification question regarding workshop production flexibility, presenting two mutually exclusive options for the user to choose from."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do the production quantities of each component have to be whole numbers (integer units), or can they be fractional?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding integer vs. fractional production quantities."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If a workshop produces more of a component than is needed to assemble the complete products, is that extra component simply wasted, or does it carry over as inventory for future use?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding excess production (waste vs. inventory)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the production rates in the table (e.g., Workshop A produces 10 units/hour of Component 1) constant regardless of how many hours are allocated, or do they change depending on the allocation?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding the nature of the production rates (constant vs. variable)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any setup time, minimum batch size, or other fixed cost associated with a workshop producing a component, or is the only constraint the total hours not exceeding capacity?"
  ],
  "rationale": "The response asks a single clarification question about whether fixed costs or minimums exist versus only capacity constraints."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any other constraints or considerations I should know about, such as labor availability, material limits, or quality requirements, or is the model fully defined by the workshop capacities and production rates?"
  ],
  "rationale": "The response asks a single clarification question regarding whether additional constraints exist or if the current definition is complete."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "should I assume production quantities can be fractional (continuous)",
    "that any component produced beyond what is needed for complete products is simply wasted (no carryover)"
  ],
  "rationale": "The response asks for confirmation on two distinct assumptions: one regarding the continuity of production quantities and another regarding the handling of excess components."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the two points still pending internal confirmation (whether quantities must be whole numbers, and whether excess components are wasted or carried over), which assumption would you prefer I use in the model — fractional quantities with excess wasted, or whole-number quantities with excess carried over?"
  ],
  "rationale": "The response asks for a single policy choice between two specific combined assumptions, rather than asking for separate answers to the underlying sub-issues."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "would you like me to proceed with the most standard assumption — fractional (continuous) quantities and excess components simply wasted — so I can deliver a model now, with the understanding that it can be adjusted once your team confirms?"
  ],
  "rationale": "The response asks a single yes/no clarification question about whether to proceed with specific assumptions."
}
